package io.knowledgebrain.activity;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
import io.knowledgebrain.contracts.learning.roadmap.v1.RoadmapEventEnvelopeV1;import io.knowledgebrain.contracts.content.attachments.v1.*;
class AttachmentActivityTest extends ActivityFixtures {
 static final String TOPIC="content.note-attachments.v1";
 NoteAttachmentV1.Builder file(){return NoteAttachmentV1.newBuilder().setAttachmentId(id().toString()).setMediaId(id().toString()).setFilename("proof<img onerror=evil> 한글.pdf").setMimeType("application/pdf").setByteSize(10485760).setSha256("a".repeat(64));}
 @Test void originalOrderedSealedMetadataKeepsIdsAndIndependentBodyVersion()throws Exception{var env=RoadmapEventEnvelopeV1.parseFrom(wire("NOTE_ATTACHMENTS",id()));var p=NoteAttachmentsChangedPayloadV1.parseFrom(env.getPayload());var a=file().build();var b=file().setFilename("image😀.png").setMimeType("image/png").setByteSize(1).build();var raw=env.toBuilder().setPayload(p.toBuilder().setAttachmentVersion(23).setNoteVersion(7).addAttachments(b).addAttachments(a).build().toByteString()).build().toByteArray();var e=ActivityEvent.decode(TOPIC,raw);assertEquals(23,e.sourceVersion());assertEquals(7,e.noteAttachments().noteVersion());assertEquals(p.getRevisionId(),e.noteAttachments().revisionId().toString());assertEquals(List.of(b.getMediaId(),a.getMediaId()),e.noteAttachments().attachments().stream().map(v->v.mediaId().toString()).toList());assertEquals(a.getFilename(),e.noteAttachments().attachments().getLast().filename());assertEquals(10485760,e.noteAttachments().attachments().getLast().byteSize());assertTrue(ActivityEvent.target(e));assertNull(e.noteLinks());assertNull(e.metadata());ActivityEvent.transport(TOPIC,raw,e.aggregateId().toString(),headers(e));}
 @Test void duplicateInvalidOversizedAndRetiredPopulatedSnapshotsAreRejected()throws Exception{var env=RoadmapEventEnvelopeV1.parseFrom(wire("NOTE_ATTACHMENTS",id()));var p=NoteAttachmentsChangedPayloadV1.parseFrom(env.getPayload());for(var bad:List.of(file().setAttachmentId("bad"),file().setMediaId("bad"),file().setFilename("../file"),file().setFilename("file\\path"),file().setFilename(" "),file().setFilename("x".repeat(201)),file().setFilename("a\n.txt"),file().setFilename("e\u0301.pdf"),file().setMimeType("text/html"),file().setByteSize(0),file().setByteSize(-1),file().setByteSize(10485761),file().setSha256("A".repeat(64))))assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode(TOPIC,env.toBuilder().setPayload(p.toBuilder().addAttachments(bad).build().toByteString()).build().toByteArray()));var f=file().build();var many=p.toBuilder();for(int i=0;i<21;i++)many.addAttachments(file());for(var bad:List.of(p.toBuilder().setNoteId(id().toString()),p.toBuilder().setRevisionId("bad"),p.toBuilder().setAttachmentVersion(0),p.toBuilder().setNoteVersion(0),p.toBuilder().setNoteState("MERGED"),p.toBuilder().setNoteState("RETIRED").addAttachments(f),p.toBuilder().addAttachments(f).addAttachments(f.toBuilder().setAttachmentId(id().toString())),p.toBuilder().addAttachments(f).addAttachments(f.toBuilder().setMediaId(id().toString())),many))assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode(TOPIC,env.toBuilder().setPayload(bad.build().toByteString()).build().toByteArray()));for(var bad:List.of(env.toBuilder().setAggregateType("Media"),env.toBuilder().setEventType("MediaUploaded"),env.toBuilder().setProducer("media-service")))assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode(TOPIC,bad.build().toByteArray()));}
 @Test void fullTwentyFilesAllSixMimeTypesAndEmptyRetirementRemainValid()throws Exception{var env=RoadmapEventEnvelopeV1.parseFrom(wire("NOTE_ATTACHMENTS",id()));var p=NoteAttachmentsChangedPayloadV1.parseFrom(env.getPayload()).toBuilder();var mime=new ArrayList<>(AttachmentActivity.MIME);for(int i=0;i<20;i++)p.addAttachments(file().setMimeType(mime.get(i%6)));assertEquals(20,ActivityEvent.decode(TOPIC,env.toBuilder().setPayload(p.build().toByteString()).build().toByteArray()).noteAttachments().attachments().size());p.clearAttachments().setNoteState("RETIRED");assertTrue(ActivityEvent.decode(TOPIC,env.toBuilder().setPayload(p.build().toByteString()).build().toByteArray()).noteAttachments().attachments().isEmpty());}
 @Test void legacyRowsAndCursorsStayCompatible(){var json=tools.jackson.databind.json.JsonMapper.builder().build();var e=ActivityEvent.decode(ActivityEvent.TOPICS.get("NOTE_LINKS"),wire("NOTE_LINKS",id()));var tree=(tools.jackson.databind.node.ObjectNode)json.valueToTree(e);tree.remove("noteAttachments");assertEquals(e,json.treeToValue(tree,ActivityEvent.class));var space=id();var row=ActivityEvent.decode(TOPIC,wire("NOTE_ATTACHMENTS",space));var q=ActivityQuery.parse(space,ActivityQueryTest.params("kind","NOTE_ATTACHMENTS","timezone","UTC"));var params=ActivityQueryTest.params("kind","NOTE_ATTACHMENTS","timezone","UTC","before",q.cursor(row));assertEquals(row.eventId(),ActivityQuery.parse(space,params).event());params.put("kind",new String[]{"NOTE"});assertThrows(RuntimeException.class,()->ActivityQuery.parse(space,params));}
}
